    public static int frOrder(int k) {
        // The k-th block a word group is tried against (D224); -1 after the last.
        if (k == 0) {
            return 400;
        }
        if (k == 1) {
            return 600;
        }
        if (k == 2) {
            return 200;
        }
        if (k == 3) {
            return 300;
        }
        if (k == 4) {
            return 100;
        }
        return -1;
    }
    public static int frHolds(int row, emon.Port.Cells gv) {
        // 1 when every predicate of `row` holds on the group columns `gv`.
        int k = 0;
        int col = 0;
        int v = 0;
        int s = 0;
        int c = 0;
        while (k < frNpred()) {
            col = frPcol(row, k);
            if (col >= 0) {
                v = emon.Port.cellsAt(gv, col);
                s = frSetting(frPset(row, k));
                c = frPcmp(row, k);
                if ((c == fcEq()) && (v != s)) {
                    return 0;
                }
                if ((c == fcNe()) && (v == s)) {
                    return 0;
                }
                if ((c == fcGe()) && ((v < 0) || (v < s))) {
                    return 0;
                }
                if ((c == fcLt()) && ((v < 0) || (v >= s))) {
                    return 0;
                }
            }
            k += 1;
        }
        return 1;
    }
    public static int frDecide(emon.Port.Cells gv) {
        // The row (an index of `fr-rows`) of the first rule that holds on the group columns `gv`, trying the blocks in `fr-order` and the
        // rows of a block in table order; -1 when none holds (the default row 190 holds for every group, so never in practice).
        int n = 29;
        int b = 0;
        int blk = 0;
        int r = 0;
        while (frOrder(b) >= 0) {
            blk = frOrder(b);
            r = 0;
            while (r < n) {
                if (frBlock(r) == blk) {
                    if (frHolds(r, gv) == 1) {
                        return r;
                    }
                }
                r += 1;
            }
            b += 1;
        }
        return -1;
    }
